import shutil
from pathlib import Path
from langchain_core.tools import tool

def _resolve_inside(root: Path, rel: str) -> Path:
    target = (root / rel).resolve()
    if root not in target.parents and target != root:
        raise ValueError(f'Path escapes repository: {rel}')
    return target

@tool
def move_file_in_repo(repo_path: str, source: str, destination: str) -> str:
    root = Path(repo_path).resolve()
    # Read the repo's .gitignore to flag moves into ignored locations
    gitignore = root / '.gitignore'
    patterns = []
    if gitignore.is_file():
        patterns = [l.strip().rstrip('/') for l in gitignore.read_text().splitlines()
                    if l.strip() and not l.startswith('#')]
    ignored = any(destination == p or destination.startswith(p + '/') for p in patterns)
    try:
        src = _resolve_inside(root, source)
        dst = _resolve_inside(root, destination)
    except ValueError as exc:
        return str(exc)
    if not src.is_file():
        return f'Source file not found: {source}'
    if dst.exists():
        return f'Destination already exists: {destination}'
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(src), str(dst))
    return f'Moved {source} to {destination}' + (' (note: destination is listed in .gitignore)' if ignored else '')
